const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>new Intl.NumberFormat('en-US').format(v), compact=v=>new Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:1}).format(v);
const date=v=>v?new Date(v).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}):'Unknown';
const el=id=>document.getElementById(id);
const state={view:'developers',query:'',language:'',sort:'stars',active:false,page:1,owner:'',interest:'',minStars:0,dateRange:'all',dateFrom:'',dateTo:''};
let developers=[],snapshot,profileLimit=24,selected=null;
function filteredDevelopers(){
 const q=state.query.trim().toLowerCase();
 return developers.filter(d=>!state.owner||d.login===state.owner).map(d=>{
  const person=[d.name,d.login,d.bio].join(' ').toLowerCase().includes(q);
  const repos=d.repos.filter(r=>matchesInterest(r,state.interest)&&r.stargazers_count>=state.minStars&&matchesDate(r)&&(!state.active||!r.archived)&&(!state.language||r.language===state.language)&&(!q||person||[r.name,r.description,r.language].join(' ').toLowerCase().includes(q)));
  return {...d,repos,total_stars:repos.reduce((n,r)=>n+r.stargazers_count,0),total_forks:repos.reduce((n,r)=>n+r.forks_count,0),latest:Math.max(0,...repos.map(r=>Date.parse(r.pushed_at)||0))};
 }).filter(d=>d.repos.length);
}
function sortDevelopers(list){return list.sort((a,b)=>({stars:b.total_stars-a.total_stars,forks:b.total_forks-a.total_forks,projects:b.repos.length-a.repos.length,recent:b.latest-a.latest}[state.sort]||b.total_stars-a.total_stars)||a.login.localeCompare(b.login));}
function projectCard(r,d){return `<article class="project"><div class="project-owner"><button class="text-button" data-profile="${esc(d.login)}"><img src="${esc(d.avatar_url)}" alt="" width="21" height="21" loading="lazy">${esc(d.login)}</button>${r.archived?'<span class="archived">Archived</span>':''}</div><div class="project-top"><a href="${esc(r.html_url)}" target="_blank" rel="noopener noreferrer">${esc(r.name)} ↗</a><span title="${num(r.stargazers_count)} stars">★ ${compact(r.stargazers_count)}</span></div><p>${esc(r.description||'No description provided.')}</p><div class="repo-meta"><span class="language-tag">${esc(r.language||'Unspecified')}</span><span>${esc(r.license.spdx_id)}</span><span>${compact(r.forks_count)} forks</span></div><div class="push-date">Last push ${date(r.pushed_at)}</div></article>`;}
function developerRow(d,i,max){return `<details class="developer"><summary class="developer-summary"><span class="rank ${i<3?'top-rank':''}">${String(i+1).padStart(2,'0')}</span><div class="identity"><img class="avatar" src="${esc(d.avatar_url)}" alt="" width="43" height="43" loading="lazy"><div class="identity-copy"><span class="developer-name">${esc(d.name||d.login)}<span class="username">@${esc(d.login)}</span></span><span class="leading-project"><b>${esc(d.repos[0]?.name)}</b> ${d.repos.length>1?' + '+(d.repos.length-1)+' more':''}</span></div></div><span class="number stars"><i aria-hidden="true">★</i>${num(d.total_stars)}<span class="star-bar" aria-hidden="true"><span style="width:${Math.max(1,d.total_stars/max*100)}%"></span></span></span><span class="number secondary projects-number">${num(d.repos.length)}</span><span class="number secondary forks-number">${compact(d.total_forks)}</span><span class="chevron" aria-hidden="true">›</span></summary><div class="project-panel"><div class="profile-line"><p>${esc(d.bio||'Explore the projects owned by @'+d.login)}${d.location?' · '+esc(d.location):''}</p><button class="profile-button" data-profile="${esc(d.login)}">Full profile ↗</button></div><div class="mini-stats"><span>${num(d.repos.length)} matching projects</span><span>${compact(d.total_forks)} forks</span><span>Last push ${date(d.latest||null)}</span></div><div class="projects">${d.repos.slice(0,4).map(r=>projectCard(r,d)).join('')}</div>${d.repos.length>4?`<button class="text-button more-projects" data-developer-projects="${esc(d.login)}">Browse all ${num(d.repos.length)} matching projects →</button>`:''}</div></details>`;}
function render(){
 const list=sortDevelopers(filteredDevelopers());let results=list;
 const advancedCount=Number(Boolean(state.interest))+Number(state.minStars>0)+Number(state.dateRange!=='all');el('advanced-filter-count').hidden=!advancedCount;el('advanced-filter-count').textContent=advancedCount+' active';
 if(state.view==='projects')results=list.flatMap(d=>d.repos.map(r=>({r,d}))).sort((a,b)=>state.sort==='recent'?(Date.parse(b.r.pushed_at)||0)-(Date.parse(a.r.pushed_at)||0):state.sort==='forks'?b.r.forks_count-a.r.forks_count:b.r.stargazers_count-a.r.stargazers_count);
 const pages=Math.max(1,Math.ceil(results.length/24));state.page=Math.min(state.page,pages);const from=(state.page-1)*24,items=results.slice(from,from+24);
 el('result-count').textContent=`${num(results.length)} ${state.view} · ${state.sort==='recent'?'latest push first':state.sort==='forks'?'most forks first':state.sort==='projects'?'most projects first':'most stars first'}`;
 if(state.owner)el('result-count').textContent+=' · @'+state.owner;el('count').textContent=num(results.length);el('table-head').hidden=state.view!=='developers';el('rows').className=state.view==='projects'?'project-browser':'';
 el('rows').innerHTML=items.length?(state.view==='developers'?items.map((d,i)=>developerRow(d,from+i,Math.max(1,...list.map(d=>d.total_stars)))).join(''):items.map(({r,d})=>projectCard(r,d)).join('')):'<div class="empty-state"><strong>No matches yet.</strong><p>Try another name, project, or language.</p><button data-reset>Clear filters</button></div>';
 el('pagination').hidden=pages<=1;el('page-label').textContent=`${from+1}–${Math.min(from+24,results.length)} of ${num(results.length)}`;el('previous').disabled=state.page===1;el('next').disabled=state.page===pages;el('reset').hidden=!(state.query||state.language||state.active||state.owner||state.interest||state.minStars||state.dateRange!=='all');document.querySelectorAll('[data-interest]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.interest===state.interest)));el('export-data').disabled=!results.length;updateDateCaption();
}
function setView(view){state.view=view;state.page=1;el('sort').querySelector('[value="projects"]').disabled=view==='projects';if(view==='projects'&&state.sort==='projects'){state.sort='stars';el('sort').value='stars';}document.querySelectorAll('[data-view]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.view===view));b.tabIndex=b.dataset.view===view?0:-1;});el('results-panel').setAttribute('aria-labelledby','tab-'+view);render();}
function reset(){Object.assign(state,{query:'',language:'',active:false,page:1,owner:'',interest:'',minStars:0,dateRange:'all',dateFrom:'',dateTo:''});el('search').value='';el('language').value='';el('active').checked=false;el('min-stars').value='0';el('date-range').value='all';el('date-from').value='';el('date-to').value='';el('custom-dates').hidden=true;render();}
function showProfile(login,updateHash=true){selected=developers.find(d=>d.login.toLowerCase()===login.toLowerCase());if(!selected)return;profileLimit=24;renderProfile();if(!el('profile-dialog').open)el('profile-dialog').showModal();if(updateHash)history.replaceState(null,'','#developer='+encodeURIComponent(selected.login));}
function renderProfile(){
 const d=selected,langs={};d.repos.forEach(r=>{if(r.language)langs[r.language]=(langs[r.language]||0)+1;});const top=Object.entries(langs).sort((a,b)=>b[1]-a[1]).slice(0,5),active=d.repos.filter(r=>!r.archived).length;
 el('profile-content').innerHTML=`<div class="profile-hero"><img class="profile-avatar" src="${esc(d.avatar_url)}" alt="" width="76" height="76"><div><h2 id="profile-title">${esc(d.name||d.login)}</h2><span>@${esc(d.login)}${d.location?' · '+esc(d.location):''}</span></div></div><p class="profile-bio">${esc(d.bio||'Open source developer on GitHub.')}</p><div class="profile-actions"><a class="profile-button" href="${esc(d.html_url)}" target="_blank" rel="noopener noreferrer">GitHub profile ↗</a><button class="profile-button" data-compare-person="${esc(d.login)}">Compare developer</button><button id="copy-profile" class="profile-button">Copy profile link</button><span id="copy-status" role="status"></span></div><section id="profile-claim" class="profile-claim" aria-label="Profile ownership and featured work"></section><div class="profile-stats"><div><strong>${compact(d.total_stars)}</strong><span>Stars</span></div><div><strong>${num(d.repos.length)}</strong><span>Projects</span></div><div><strong>${compact(d.total_forks)}</strong><span>Forks</span></div><div><strong>${compact(d.followers)}</strong><span>Followers</span></div></div><div class="language-breakdown"><h3>Languages across projects</h3>${top.map(([l,n])=>`<div><span>${esc(l)}</span><i><b style="width:${n/d.repos.length*100}%"></b></i><span>${n} projects</span></div>`).join('')||'<p>No language data.</p>'}</div><p class="profile-coverage">${num(active)} non-archived · ${num(d.repos.length-active)} archived · ${num(d.excluded_repos)} repositories excluded by eligibility rules<br>Profile snapshot: ${date(d.fetched_at||snapshot)}. All eligible personal repositories; leaderboard filters do not apply here.</p><h3 class="profile-project-heading">Projects <span>${Math.min(profileLimit,d.repos.length)} of ${num(d.repos.length)}</span></h3><div class="projects">${d.repos.slice(0,profileLimit).map(r=>projectCard(r,d)).join('')}</div>${profileLimit<d.repos.length?'<button id="load-profile-projects" class="profile-button load-more">Show 24 more projects</button>':''}`;
 window.starboardProfile=d;document.dispatchEvent(new CustomEvent('starboard:profile',{detail:d}));
}
document.addEventListener('starboard:open-profile',e=>showProfile(e.detail));
async function init(){
 try{
  const response=await fetch('/data.json');if(!response.ok)throw new Error('Snapshot unavailable');const data=await response.json();snapshot=data.fetched_at;developers=data.developers.filter(d=>d.repos.length).sort((a,b)=>b.total_stars-a.total_stars);if(!developers.length)throw new Error('No profiles');window.starboardDevelopers=developers;document.dispatchEvent(new Event('starboard:ready'));
  el('developer-count').textContent=num(developers.length);el('project-count').textContent=num(developers.reduce((n,d)=>n+d.repos.length,0));el('star-count').textContent=compact(developers.reduce((n,d)=>n+d.total_stars,0));el('snapshot-date').textContent=date(snapshot);el('data-time').textContent='Dataset assembled '+new Date(snapshot).toUTCString()+'. Profiles show their own snapshot dates. Automatic refresh is not configured.';
  const languages=[...new Set(developers.flatMap(d=>d.repos.map(r=>r.language)).filter(Boolean))].sort();el('language').insertAdjacentHTML('beforeend',languages.map(l=>`<option>${esc(l)}</option>`).join(''));
  el('search').addEventListener('input',e=>{state.query=e.target.value;state.owner='';state.page=1;render();});el('language').addEventListener('change',e=>{state.language=e.target.value;state.page=1;render();});el('sort').addEventListener('change',e=>{state.sort=e.target.value;state.page=1;render();});el('active').addEventListener('change',e=>{state.active=e.target.checked;state.page=1;render();});el('reset').addEventListener('click',reset);
  document.querySelectorAll('[data-view]').forEach(b=>{b.addEventListener('click',()=>setView(b.dataset.view));b.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const view=e.key==='Home'?'developers':e.key==='End'?'projects':state.view==='developers'?'projects':'developers';setView(view);el('tab-'+view).focus();}});});
  for(const [id,delta] of [['previous',-1],['next',1]])el(id).addEventListener('click',()=>{state.page+=delta;render();el('board-title').scrollIntoView({block:'start'});});
  document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.profile)showProfile(b.dataset.profile);if(b.dataset.developerProjects){state.owner=b.dataset.developerProjects;setView('projects');}if(b.hasAttribute('data-reset'))reset();if(b.id==='load-profile-projects'){profileLimit+=24;const scroll=el('profile-dialog').scrollTop;renderProfile();el('profile-dialog').scrollTop=scroll;el('load-profile-projects')?.focus({preventScroll:true});}if(b.id==='copy-profile'){try{await navigator.clipboard.writeText(location.href);el('copy-status').textContent='Link copied';}catch{el('copy-status').textContent='Copy the URL from your address bar.';}}});
  el('close-profile').addEventListener('click',()=>el('profile-dialog').close());el('profile-dialog').addEventListener('close',()=>{if(location.hash.startsWith('#developer='))history.replaceState(null,'',location.pathname+location.search);});el('profile-dialog').addEventListener('click',e=>{if(e.target===el('profile-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
  render();initEnhancements();const hash=new URLSearchParams(location.hash.slice(1));if(hash.has('developer'))showProfile(hash.get('developer'),false);
 }catch(error){el('rows').innerHTML='<p class="loading">The developer snapshot could not be loaded. Reload the page to try again.</p>';el('snapshot-date').textContent='Unavailable';el('result-count').textContent='Snapshot unavailable';}
}
init();
